// === Tab: mySketch ===
let tx;
let img;
function setup() {

  createCanvas(800, 600,WEBGL);
	rectMode(CENTER);
  img = loadImage('https://openprocessing.org/sketch/1149747/files/ts.png');
  tx = createShader(vert, frag);
	}

function draw() {  
	this.shader(tx);
  background(0);
	tx.setUniform('resolution',[width,height]);
	tx.setUniform('time',millis()/20);
	tx.setUniform('tex0', img);

   // rect gives us some geometry on the screen
   rect(0,0,width,height);

}

// === Tab: shader ===

var vert=`
attribute vec3 aPosition;
attribute vec2 aTexCoord;

varying vec2 vTexCoord;

void main() {

    vTexCoord = aTexCoord;
    vec4 positionVec4 = vec4(aPosition, 1.0);
    positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
    gl_Position = positionVec4;
}
`;
var frag=`

precision mediump float;

varying vec2 vTexCoord;

uniform sampler2D tex0; // texture image
uniform float time;

float freq = 8.0;
float amp  = 1.2;

void main() {
    vec2 uv = vTexCoord;
		uv.y = 1.-uv.y;   // uv flip y ;

    vec2 pl = sin(time*0.2 - freq * uv);
    float d = 2.0 * length(uv.y - 0.5);

    vec2 c = uv + (amp/50.) * vec2(pl.y*1.6, pl.x*0.8); // y-axis only;
		float scl1 = abs(sin(10.*mod(gl_FragCoord.y*gl_FragCoord.x, 3.0)));
    float scl2 = mod(gl_FragCoord.x, 3.0)-mod(gl_FragCoord.y, 3.0);

    vec2 c2 = mix(c, uv, d);


    vec4 tx = texture2D(tex0, c2)*scl1;


    // render the output
    gl_FragColor = vec4(tx);

		// cut the edges
		if(c2.x > 1. || c2.y > 1. || c2.x < 0. || c2.y < 0.)
       gl_FragColor = vec4(0.,0.,0.,0.); // clear avec alpha


}

`

